INSERT INTO "AssessmentInstrument" ("id", "code", "name", "items", "scoring", "isActive") VALUES
('seed_instr_phq9', 'PHQ9', 'Cuestionario de salud del paciente (PHQ-9)', '[{"text":"Poco interés o placer en hacer cosas","options":[{"label":"Ninguna vez","value":0},{"label":"Varios días","value":1},{"label":"Más de la mitad de los días","value":2},{"label":"Casi todos los días","value":3}]},{"text":"Me he sentido triste, deprimido/a o sin esperanzas","options":[{"label":"Ninguna vez","value":0},{"label":"Varios días","value":1},{"label":"Más de la mitad de los días","value":2},{"label":"Casi todos los días","value":3}]},{"text":"Dificultad para quedarme o permanecer dormido/a, o dormir demasiado","options":[{"label":"Ninguna vez","value":0},{"label":"Varios días","value":1},{"label":"Más de la mitad de los días","value":2},{"label":"Casi todos los días","value":3}]},{"text":"Me he sentido cansado/a o con poca energía","options":[{"label":"Ninguna vez","value":0},{"label":"Varios días","value":1},{"label":"Más de la mitad de los días","value":2},{"label":"Casi todos los días","value":3}]},{"text":"Poco apetito o he comido en exceso","options":[{"label":"Ninguna vez","value":0},{"label":"Varios días","value":1},{"label":"Más de la mitad de los días","value":2},{"label":"Casi todos los días","value":3}]},{"text":"Me he sentido mal conmigo mismo/a, o que soy un fracaso o que he quedado mal conmigo mismo/a o con mi familia","options":[{"label":"Ninguna vez","value":0},{"label":"Varios días","value":1},{"label":"Más de la mitad de los días","value":2},{"label":"Casi todos los días","value":3}]},{"text":"Dificultad para concentrarme en cosas, como leer el periódico o ver televisión","options":[{"label":"Ninguna vez","value":0},{"label":"Varios días","value":1},{"label":"Más de la mitad de los días","value":2},{"label":"Casi todos los días","value":3}]},{"text":"Me he movido o hablado tan lento que otras personas podrían notarlo, o todo lo contrario: he estado tan inquieto/a o agitado/a que me he movido mucho más de lo acostumbrado","options":[{"label":"Ninguna vez","value":0},{"label":"Varios días","value":1},{"label":"Más de la mitad de los días","value":2},{"label":"Casi todos los días","value":3}]},{"text":"He tenido pensamientos de que estaría mejor muerto/a o de lastimarme de alguna forma","options":[{"label":"Ninguna vez","value":0},{"label":"Varios días","value":1},{"label":"Más de la mitad de los días","value":2},{"label":"Casi todos los días","value":3}]}]', '{"type":"sum","ranges":[{"min":0,"max":4,"label":"Leve"},{"min":5,"max":9,"label":"Leve-moderado"},{"min":10,"max":14,"label":"Moderado"},{"min":15,"max":19,"label":"Moderado-severo"},{"min":20,"max":27,"label":"Severo"}]}', true),
('seed_instr_gad7', 'GAD7', 'Escala de ansiedad generalizada (GAD-7)', '[{"text":"Me he sentido nervioso/a, ansioso/a o con los nervios de punta","options":[{"label":"Ninguna vez","value":0},{"label":"Varios días","value":1},{"label":"Más de la mitad de los días","value":2},{"label":"Casi todos los días","value":3}]},{"text":"No he podido dejar de preocuparme","options":[{"label":"Ninguna vez","value":0},{"label":"Varios días","value":1},{"label":"Más de la mitad de los días","value":2},{"label":"Casi todos los días","value":3}]},{"text":"Me he preocupado demasiado por diferentes cosas","options":[{"label":"Ninguna vez","value":0},{"label":"Varios días","value":1},{"label":"Más de la mitad de los días","value":2},{"label":"Casi todos los días","value":3}]},{"text":"He tenido dificultad para relajarme","options":[{"label":"Ninguna vez","value":0},{"label":"Varios días","value":1},{"label":"Más de la mitad de los días","value":2},{"label":"Casi todos los días","value":3}]},{"text":"Me he sentido tan inquieto/a que me ha sido difícil permanecer sentado/a quieto/a","options":[{"label":"Ninguna vez","value":0},{"label":"Varios días","value":1},{"label":"Más de la mitad de los días","value":2},{"label":"Casi todos los días","value":3}]},{"text":"Me he molestado o irritado fácilmente","options":[{"label":"Ninguna vez","value":0},{"label":"Varios días","value":1},{"label":"Más de la mitad de los días","value":2},{"label":"Casi todos los días","value":3}]},{"text":"He sentido miedo, como si algo terrible fuera a suceder","options":[{"label":"Ninguna vez","value":0},{"label":"Varios días","value":1},{"label":"Más de la mitad de los días","value":2},{"label":"Casi todos los días","value":3}]}]', '{"type":"sum","ranges":[{"min":0,"max":4,"label":"Leve"},{"min":5,"max":9,"label":"Leve-moderado"},{"min":10,"max":14,"label":"Moderado"},{"min":15,"max":21,"label":"Severo"}]}', true),
('seed_instr_who5', 'WHO5', 'Índice de bienestar de la OMS (WHO-5)', '[{"text":"Me he sentido alegre y de buen humor","options":[{"label":"En ningún momento","value":0},{"label":"Rara vez","value":1},{"label":"Alguna vez","value":2},{"label":"A menudo","value":3},{"label":"La mayoría de las veces","value":4},{"label":"Todo el tiempo","value":5}]},{"text":"Me he sentido tranquilo/a y relajado/a","options":[{"label":"En ningún momento","value":0},{"label":"Rara vez","value":1},{"label":"Alguna vez","value":2},{"label":"A menudo","value":3},{"label":"La mayoría de las veces","value":4},{"label":"Todo el tiempo","value":5}]},{"text":"Me he sentido activo/a y con energía","options":[{"label":"En ningún momento","value":0},{"label":"Rara vez","value":1},{"label":"Alguna vez","value":2},{"label":"A menudo","value":3},{"label":"La mayoría de las veces","value":4},{"label":"Todo el tiempo","value":5}]},{"text":"Me he despertado sintiéndome fresco/a y descansado/a","options":[{"label":"En ningún momento","value":0},{"label":"Rara vez","value":1},{"label":"Alguna vez","value":2},{"label":"A menudo","value":3},{"label":"La mayoría de las veces","value":4},{"label":"Todo el tiempo","value":5}]},{"text":"Mi vida diaria ha estado llena de cosas que me interesan","options":[{"label":"En ningún momento","value":0},{"label":"Rara vez","value":1},{"label":"Alguna vez","value":2},{"label":"A menudo","value":3},{"label":"La mayoría de las veces","value":4},{"label":"Todo el tiempo","value":5}]}]', '{"type":"sum","ranges":[{"min":0,"max":12,"label":"Bajo bienestar"},{"min":13,"max":25,"label":"Bienestar aceptable"}]}', true)
